import numpy as np, scipy.sparse as sp, scipy.sparse.linalg as sla, random, time
N=1000; k=5; density=0.01
seeds=random.sample(range(10**6),100)

def trial(tol):
    for seed in seeds:
        rng=np.random.default_rng(seed)
        A=sp.random(N,N,density,'csr',data_rvs=rng.standard_normal)
        vals_cand, vecs_cand = sla.eigs(A,k=k,v0=np.ones(N),ncv=35,maxiter=N*200,tol=tol)
        vals_ref, vecs_ref = sla.eigs(A,k=k,v0=np.ones(N),ncv=20,maxiter=N*200)
        idx_ref=np.argsort(-np.abs(vals_ref)); vecs_ref=vecs_ref[:,idx_ref]
        idx=np.argsort(-np.abs(vals_cand)); vecs_cand=vecs_cand[:,idx]
        for i in range(k):
            sim=np.abs(np.vdot(vecs_cand[:,i], vecs_ref[:,i]))/(np.linalg.norm(vecs_cand[:,i])*np.linalg.norm(vecs_ref[:,i]))
            if not np.isclose(sim,1.0,atol=1e-6):
                return False
    return True
for tol in [0, 1e-10,1e-8,1e-6,1e-5,1e-4]:
    print(tol, trial(tol))
