import numpy as np, scipy.sparse as sp, scipy.sparse.linalg as sla, random, time, os
os.environ['OMP_NUM_THREADS']='4'
N=1000; k=5; density=0.01
params_list=[]
for ncv in [10,15,20,25,30,35]:
  for maxiter_factor in [20,30,40,50,80,100,150,200]:
    for tol in [0]:
      params_list.append((ncv,maxiter_factor,tol))
print('testing',len(params_list))
seed_list=random.sample(range(1000000),50)
ref_time_tot=0.0
for seed in seed_list:
  rng=np.random.default_rng(seed)
  A=sp.random(N,N,density,'csr',data_rvs=rng.standard_normal)
  t=time.perf_counter(); sla.eigs(A,k=k,v0=np.ones(N),ncv=20,maxiter=N*200); ref_time_tot+=time.perf_counter()-t
ref_time=ref_time_tot/len(seed_list)
print('ref avg', ref_time)

def is_correct(A, vecs):
  vals_r, vecs_r = sla.eigs(A,k=k,v0=np.ones(N),ncv=20,maxiter=N*200)
  idx_r=np.argsort(-np.abs(vals_r)); vecs_r=vecs_r[:,idx_r]
  for i in range(k):
    sim=np.abs(np.vdot(vecs[:,i],vecs_r[:,i]))/(np.linalg.norm(vecs[:,i])*np.linalg.norm(vecs_r[:,i]))
    if not np.isclose(sim,1.0,atol=1e-6):
      return False
  return True
best=None
for ncv,maxiter_factor,tol in params_list:
  start=time.perf_counter();
  ok=True
  total=0.0
  for seed in seed_list[:20]:
    rng=np.random.default_rng(seed)
    A=sp.random(N,N,density,'csr',data_rvs=rng.standard_normal)
    try:
      t0=time.perf_counter(); vals, vecs = sla.eigs(A,k=k,v0=np.ones(N),ncv=ncv,maxiter=N*maxiter_factor,tol=tol); total+=time.perf_counter()-t0
    except Exception:
      ok=False; break
    idx=np.argsort(-np.abs(vals)); vecs=vecs[:,idx]
    if not is_correct(A, vecs):
      ok=False; break
  if ok:
    avg=total/20
    speedup=ref_time/avg
    if best is None or speedup>best[0]:
      best=(speedup, ncv,maxiter_factor,tol, avg)
      print('new best', best)
print('Best found', best)
