import numpy as np, scipy.sparse as sp, scipy.sparse.linalg as sla, random, time, os
os.environ['OMP_NUM_THREADS']='4'

def test(N, trials=200):
    k=5; density=0.01
    success=0; fails=0; start=time.perf_counter()
    for seed in range(trials):
        rng=np.random.default_rng(seed)
        A=sp.random(N,N,density,'csr',data_rvs=rng.standard_normal)
        try:
            vals_cand, vecs_cand = sla.eigs(A,k=k,v0=np.ones(N),ncv=max(2*k+1,20),maxiter=N*10)  # fast
        except Exception as e:
            fails+=1; continue
        vals_ref, vecs_ref = sla.eigs(A,k=k,v0=np.ones(N),ncv=20,maxiter=N*200)
        idx_ref=np.argsort(-np.abs(vals_ref)); vecs_ref=vecs_ref[:,idx_ref]
        idx=np.argsort(-np.abs(vals_cand)); vecs_cand=vecs_cand[:,idx]
        good=True
        for i in range(k):
            sim=np.abs(np.vdot(vecs_cand[:,i], vecs_ref[:,i]))/(np.linalg.norm(vecs_cand[:,i])*np.linalg.norm(vecs_ref[:,i]))
            if not np.isclose(sim,1.0,atol=1e-6):
                good=False; break
        if good:
            success+=1
    print('N',N,'success',success,'fails',trials-success);
    print('elapsed', time.perf_counter()-start)

test(300, trials=100)
test(1000, trials=60)
