for seed in range(trials):
    rng=np.random.default_rng(seed)
    A=sp.random(N,N,density,'csr',data_rvs=rng.standard_normal)
    try:
        vals, vecs = sla.eigs(A,k=k,v0=np.ones(N),ncv=20,maxiter=N*20,tol=1e-3)
    except sla.ArpackNoConvergence as exc:
        if exc.eigenvectors is not None and exc.eigenvectors.shape[1]==k:
            vals, vecs = exc.eigenvalues, exc.eigenvectors
        else:
            fail+=1; continue
    # verify
    vals_ref, vecs_ref = sla.eigs(A,k=k,v0=np.ones(N),ncv=20,maxiter=N*200)
    idx_ref=np.argsort(-np.abs(vals_ref)); vecs_ref=vecs_ref[:,idx_ref]
    idx=np.argsort(-np.abs(vals)); vecs=vecs[:,idx]
    ok=True
    for i in range(k):
        sim=np.abs(np.vdot(vecs[:,i], vecs_ref[:,i]))/(np.linalg.norm(vecs[:,i])*np.linalg.norm(vecs_ref[:,i]))
        if sim < 1-1e-6:
            ok=False; break
    if ok:
        success+=1
    else:
        fail+=1
print('success',success,'fail',fail)
